labels=['300000','1100000','best_1175000','2000384'];data={l:json.loads((p/f'episodes_{l}.json').read_text()) for l in labels}
def wilson(k,n):
 z=1.96;v=k/n;d=1+z*z/n;c=(v+z*z/(2*n))/d;h=z*np.sqrt(v*(1-v)/n+z*z/(4*n*n))/d;return [c-h,c+h]
summary={}
for l,rows in data.items():
 summary[l]={}
 for g in ['all']+sorted(set(r['group'] for r in rows)):
  a=[r for r in rows if r['group']!='viewer'] if g=='all' else [r for r in rows if r['group']==g]
  n=len(a);k=sum(r['success'] for r in a)
  summary[l][g]=dict(n=n,success=k,collision=sum(r['collision'] for r in a),timeout=sum(r['timeout'] for r in a),success_ci95=wilson(k,n),median_est_error=float(np.median([r['final_est_error'] for r in a])),mean_reward=float(np.mean([r['reward'] for r in a])))
paired={};rng=np.random.default_rng(27)
for old in labels[:-1]:
 a={r['seed']:r for r in data[old]};b={r['seed']:r for r in data['2000384'] if r['group']!='viewer'}
 assert set(a)==set(b) and all(a[k]['fingerprint']==b[k]['fingerprint'] for k in a)
 delta=np.array([int(b[k]['success'])-int(a[k]['success']) for k in a]);gain=int(np.sum(delta==1));loss=int(np.sum(delta==-1))
 boot=delta[rng.integers(len(delta),size=(10000,len(delta)))].mean(1)
 paired[old]=dict(success_change=float(delta.mean()),ci95=np.quantile(boot,[.025,.975]).tolist(),gained=gain,lost=loss,mcnemar_exact_p=binomtest(gain,gain+loss).pvalue if gain+loss else 1.)
(p/'summary.json').write_text(json.dumps(dict(results=summary,paired=paired),indent=2))
fig,axes=plt.subplots(1,2,figsize=(12,4));x=np.arange(5)
for i,l in enumerate(labels):
 axes[0].bar(x+(i-1.5)*.19,[summary[l][f'level_{g}']['success']/24 for g in range(1,6)],.19,label=l)
