for ax in axes:ax.set_ylim(0,1);ax.grid(axis='y',alpha=.2);ax.legend(fontsize=8)
axes[0].set_xticks(x,['Vazia','Uma caixa','2–6 caixas','Arena real','Ruído']);axes[0].set_title('Sucesso — mesmas 120 sementes por checkpoint');axes[1].set_title('Colisões por nível');axes[1].set_xlabel('Nível');fig.tight_layout();fig.savefig(p/'comparacao.png',dpi=160);plt.close(fig)
