for g in range(1,6):ax.plot([v['steps'] for v in history['evaluations']],[v['summary'][f'level_{g}']['success'] for v in history['evaluations']],label=f'Nível {g}',alpha=.7)
for b in [300000,700000,1100000,1600000]:ax.axvline(b,color='gray',alpha=.3)
ax.set(xlabel='Passos',ylabel='Sucesso',title='Avaliações históricas: apenas 3 sementes fixas por nível');ax.legend();fig.tight_layout();fig.savefig(p/'historico.png',dpi=160);plt.close(fig)
