for ax,r in zip(axes,chosen):
 idx=r['seed']-(2300000000+r['level']*10000);f=p/f"2000384_{r['group']}_{idx}.npz";d=np.load(f);t=d['trajectory'];cells=d['cells'];res=float(d['resolution']);origin=d['origin'];c,s=np.cos(origin[2]),np.sin(origin[2]);rot=np.array([[c,-s],[s,c]])
 from matplotlib.transforms import Affine2D
 tr=Affine2D().rotate(origin[2]).translate(*origin[:2])+ax.transData
 ax.imshow(np.where(cells==0,1.,np.where(cells==1,0.,.5)),origin='lower',extent=[0,cells.shape[1]*res,0,cells.shape[0]*res],transform=tr,cmap='gray',vmin=0,vmax=1)
 ax.plot(t[:,0],t[:,1],label='Pose física');ax.plot(t[:,3],t[:,4],linestyle='--',label='Pose estimada');ax.scatter(*d['goal'],marker='*',c='green',s=100,label='Alvo');ax.scatter(*t[0,:2],c='purple',s=20)
