for level in range(2,6):
 a=[r for r in accepted if r['level']==level];geo.append(dict(level=level,n=len(a),clipped=sum(r['clipped'] for r in a),overlap=sum(r['overlap_blocked'] for r in a),unknown=sum(r['overlap_unknown'] for r in a)))
